// Source: js/runner/languages/mermaid/index.js
/**
 * MermaidRunner - Mermaid 图表渲染器
 * 
 * 将 Mermaid DSL 代码渲染为 SVG 图表，作为 Runner 体系的一种"预览型"语言。
 * 行为类似 MarkdownRunner / HtmlRunner：不执行代码，只渲染预览。
 * 
 * 依赖：mermaid.min.js（全局 window.mermaid）
 */

class MermaidRunner extends BaseRunner {
    constructor() {
        super({
            language: 'mermaid',
            displayName: 'Mermaid',
            icon: '📊',
            fileExtension: '.mmd'
        });
        this._idCounter = 0;
    }

    /**
     * 生成唯一渲染 ID
     */
    _uniqueId() {
        return `mermaid-run-${Date.now().toString(36)}-${(this._idCounter++).toString(36)}`;
    }

    /**
     * 清理特殊空白字符
     */
    _sanitize(code) {
        return code
            .replace(/[\u00A0\u2002\u2003\u2009\u200A\u3000]/g, ' ')
            .replace(/[\u200B\u200C\u200D\u200E\u200F\uFEFF]/g, '');
    }

    /**
     * 配置 mermaid 实例
     * 固定使用浅色主题，因为 Runner 输出面板中的预览容器始终是白底
     */
    _configure() {
        if (typeof mermaid === 'undefined') return false;

        mermaid.initialize({
            startOnLoad: false,
            theme: 'default',
            securityLevel: 'loose',
            fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif',
            logLevel: 'error'
        });
        return true;
    }

    /**
     * 执行（渲染）Mermaid 代码
     * @param {string} code - Mermaid 源码
     * @param {Object} options
     * @returns {Promise}
     */
    async execute(code, options = {}) {
        const startTime = Date.now();
        const { onOutput = () => {} } = options;

        try {
            if (typeof mermaid === 'undefined') {
                throw new Error('Mermaid library not loaded');
            }

            this._configure();

            const cleaned = this._sanitize(code);
            const id = this._uniqueId();

            // 兼容 v8 (回调/同步) 和 v10+ (Promise)
            const renderFn = mermaid.render || mermaid.mermaidAPI?.render;
            if (!renderFn) throw new Error('mermaid.render not available');

            let svg = null;
            const result = renderFn.call(mermaid, id, cleaned);

            if (result && typeof result.then === 'function') {
                // v10+
                const resolved = await result;
                svg = typeof resolved === 'string' ? resolved : resolved?.svg || null;
            } else if (typeof result === 'string' && result.includes('<svg')) {
                // v8/v9 同步返回
                svg = result;
            } else {
                // v8 回调 fallback
                svg = await new Promise((resolve) => {
                    try {
                        renderFn.call(mermaid, id, cleaned, (s) => resolve(s || null));
                    } catch { resolve(null); }
                });
            }

            if (!svg) throw new Error('Mermaid render returned empty result');

            onOutput({
                level: 'mermaid-preview',
                data: { svg: svg }
            });

            return {
                success: true,
                duration: Date.now() - startTime,
                language: this.language
            };
        } catch (error) {
            // 清理 mermaid 可能遗留的错误 DOM
            document.querySelectorAll('[id^="mermaid-run-"][id*="d"]').forEach(el => {
                if (!el.closest('.runner-container')) el.remove();
            });

            onOutput({
                level: 'error',
                data: [error.message || 'Mermaid render failed']
            });

            return {
                success: false,
                error: error.message,
                language: this.language
            };
        }
    }

    cleanup() {}

    getPlaceholder() {
        return 'graph TD\n    A[Start] --> B[End]';
    }

    getExampleCode() {
        return `graph TD
    A[Start] --> B{Decision}
    B -->|Yes| C[Process A]
    B -->|No| D[Process B]
    C --> E[End]
    D --> E`;
    }
}

// 导出
if (typeof window !== 'undefined') {
    window.MermaidRunner = MermaidRunner;
}

;

// Source: js/runner/languages/registry.js
/**
 * LanguageRegistry - 语言运行器注册表
 * 
 * 管理所有支持的编程语言及其运行器
 * 语言配置来自全局 RUNNER_LANGUAGES（constants.js）
 */

class LanguageRegistry {
    constructor() {
        this.runners = new Map();
        // 使用全局语言配置
        this.languageConfigs = this._buildLanguageConfigs();
        this.initialize();
    }

    /**
     * 从全局 RUNNER_LANGUAGES 构建语言配置
     * @returns {Array}
     */
    _buildLanguageConfigs() {
        return RUNNER_LANGUAGES.map(lang => ({
            id: lang.id,
            name: lang.name,
            enabled: true,
            runnerClass: lang.runnerClass
        }));
    }

    /**
     * 初始化注册所有语言
     */
    initialize() {
        // 根据配置动态注册运行器
        this.languageConfigs.forEach(config => {
            if (window[config.runnerClass]) {
                this.register(config.id, new window[config.runnerClass]());
        }
        });
    }

    /**
     * 注册一个语言运行器
     * @param {string} language - 语言标识符
     * @param {Object} runner - 运行器实例
     */
    register(language, runner) {
        this.runners.set(language, runner);
    }

    /**
     * 获取指定语言的运行器
     * @param {string} language - 语言标识符
     * @returns {Object|null}
     */
    getRunner(language) {
        return this.runners.get(language) || null;
    }

    /**
     * 检查语言是否被支持
     * @param {string} language - 语言标识符
     * @returns {boolean}
     */
    isSupported(language) {
        return this.runners.has(language);
    }

    /**
     * 获取所有支持的语言列表
     * @returns {Array}
     */
    getSupportedLanguages() {
        const languages = [];
        this.runners.forEach((runner, language) => {
            languages.push({
                id: language,
                name: runner.displayName || language,
                enabled: true
            });
        });
        return languages;
    }

    /**
     * 获取所有语言（包括未来支持的）
     * @returns {Array}
     */
    getAllLanguages() {
        return this.languageConfigs;
    }

    /**
     * 获取语言配置
     * @param {string} language - 语言标识符
     * @returns {Object|null}
     */
    getLanguageConfig(language) {
        return this.languageConfigs.find(c => c.id === language) || null;
    }

    /**
     * 清理所有运行器
     */
    cleanup() {
        this.runners.forEach(runner => {
            if (runner.cleanup) {
                runner.cleanup();
            }
        });
    }
}

// 导出
if (typeof window !== 'undefined') {
    window.LanguageRegistry = LanguageRegistry;
}

;

// Source: js/runner/runner-manager.js
/**
 * RunnerManager - 代码运行器核心管理器
 * 
 * 协调各个模块，管理代码执行流程
 */

class RunnerManager {
    constructor() {
        this.languageRegistry = null;
        this.currentLanguage = 'javascript';
        this.isRunning = false;
        this.outputLimit = 1000; // 最多显示 1000 条输出
        this.outputCount = 0;
    }

    /**
     * 初始化
     */
    initialize() {
        if (!this.languageRegistry) {
            this.languageRegistry = new window.LanguageRegistry();
        }
    }

    /**
     * 运行代码
     * @param {string} code - 要执行的代码
     * @param {string} language - 语言类型
     * @param {Object} callbacks - 回调函数
     * @returns {Promise}
     */
    async run(code, language, callbacks = {}) {
        this.initialize();

        const {
            onStart = () => {},
            onOutput = () => {},
            onComplete = () => {},
            onError = () => {}
        } = callbacks;

        // 检查代码是否为空
        if (!code || !code.trim()) {
            onError({ message: '代码不能为空' });
            return { success: false, error: '代码不能为空' };
        }

        // 检查语言是否支持
        const runner = this.languageRegistry.getRunner(language);
        if (!runner) {
            onError({ message: `不支持的语言: ${language}` });
            return { success: false, error: `不支持的语言: ${language}` };
        }

        // 检查是否正在运行
        if (this.isRunning) {
            onError({ message: '代码正在运行中，请稍候...' });
            return { success: false, error: '代码正在运行中' };
        }

        try {
            if (language === 'mermaid') {
                await window.AITResourceLoader?.load('runner-mermaid');
            } else if (language === 'markdown') {
                await window.AITResourceLoader?.load('runner-markdown');
            }
        } catch (error) {
            const errorResult = { message: error.message || '运行器依赖加载失败' };
            onError(errorResult);
            return { success: false, error: errorResult.message };
        }

        // 重置输出计数
        this.outputCount = 0;
        this.isRunning = true;
        onStart();

        try {
            // 执行代码（使用各语言默认的超时时间）
            const result = await runner.execute(code, {
                onOutput: (output) => {
                    this.handleOutput(output, onOutput);
                }
            });

            this.isRunning = false;
            onComplete(result);
            return result;

        } catch (error) {
            this.isRunning = false;
            const errorResult = {
                success: false,
                error: error.message
            };
            onError(errorResult);
            return errorResult;
        }
    }

    /**
     * 处理输出
     * @param {Object} output - 输出数据
     * @param {Function} callback - 回调函数
     */
    handleOutput(output, callback) {
        // 检查输出限制
        if (this.outputCount >= this.outputLimit) {
            if (this.outputCount === this.outputLimit) {
                callback({
                    level: 'warn',
                    data: [`输出已达到上限 (${this.outputLimit} 条)，后续输出将被忽略...`],
                    truncated: true
                });
                this.outputCount++;
            }
            return;
        }

        this.outputCount++;
        callback(output);
    }

    /**
     * 停止当前运行
     */
    stop() {
        if (!this.isRunning) return;

        // 清理当前语言的运行器
        const runner = this.languageRegistry.getRunner(this.currentLanguage);
        if (runner && runner.cleanup) {
            runner.cleanup();
        }

        this.isRunning = false;
    }

    /**
     * 验证代码语法
     * @param {string} code - 代码
     * @param {string} language - 语言
     * @returns {Object}
     */
    validateSyntax(code, language) {
        this.initialize();

        const runner = this.languageRegistry.getRunner(language);
        if (!runner) {
            return { valid: false, error: '不支持的语言' };
        }

        if (runner.validateSyntax) {
            return runner.validateSyntax(code);
        }

        return { valid: true };
    }

    /**
     * 获取示例代码
     * @param {string} language - 语言
     * @returns {string}
     */
    getExampleCode(language) {
        this.initialize();

        const runner = this.languageRegistry.getRunner(language);
        if (runner && runner.getExampleCode) {
            return runner.getExampleCode();
        }

        return '';
    }

    /**
     * 获取所有语言
     * @returns {Array}
     */
    getAllLanguages() {
        this.initialize();
        return this.languageRegistry.getAllLanguages();
    }

    /**
     * 设置当前语言
     * @param {string} language - 语言
     */
    setCurrentLanguage(language) {
        this.currentLanguage = language;
    }

    /**
     * 获取当前语言
     * @returns {string}
     */
    getCurrentLanguage() {
        return this.currentLanguage;
    }

    /**
     * 清理资源
     */
    cleanup() {
        this.stop();
        if (this.languageRegistry) {
            this.languageRegistry.cleanup();
        }
    }
}

// 导出
if (typeof window !== 'undefined') {
    window.RunnerManager = RunnerManager;
}

;

